    28→////////////////////////////////////////////////////////////////////////////////////////////////////
    29→// Vanishing Polynomial
    30→////////////////////////////////////////////////////////////////////////////////////////////////////
    31→
    32→/**
    33→ * Calculates the minimal polynomial that evaluates to zero for each root.
    34→ *
    35→ * Uses straightforward long multiplication to calculate the product of `(x - r_i)` where `r_i` is
    36→ * the i'th root. This results in a poly of degree roots_len.
    37→ *
    38→ * @param[in,out]   poly        The zero polynomial for roots, length `poly_len`
    39→ * @param[in,out]   poly_len    The length of poly
    40→ * @param[in]       roots       The array of roots, length `roots_len`
    41→ * @param[in]       roots_len   The number of roots
    42→ *
    43→ * @remark These do not have to be roots of unity. They are roots of a polynomial.
    44→ * @remark The `poly` array must be at least `roots_len + 1` in length.
    45→ */
    46→static C_KZG_RET compute_vanishing_polynomial_from_roots(
    47→    fr_t *poly, size_t *poly_len, const fr_t *roots, size_t roots_len
    48→) {
    49→    fr_t neg_root;
    50→
    51→    if (roots_len == 0) {
    52→        return C_KZG_BADARGS;
    53→    }
    54→
    55→    /* Initialize with -root[0] */
    56→    blst_fr_cneg(&poly[0], &roots[0], true);
    57→
    58→    for (size_t i = 1; i < roots_len; i++) {
    59→        blst_fr_cneg(&neg_root, &roots[i], true);
    60→
    61→        poly[i] = neg_root;
    62→        blst_fr_add(&poly[i], &poly[i], &poly[i - 1]);
    63→
    64→        for (size_t j = i - 1; j > 0; j--) {
    65→            blst_fr_mul(&poly[j], &poly[j], &neg_root);
    66→            blst_fr_add(&poly[j], &poly[j], &poly[j - 1]);
    67→        }
    68→        blst_fr_mul(&poly[0], &poly[0], &neg_root);
    69→    }
    70→
    71→    poly[roots_len] = FR_ONE;
    72→    *poly_len = roots_len + 1;
    73→
    74→    return C_KZG_OK;
    75→}
    76→
    77→/**
    78→ * Computes the minimal polynomial that evaluates to zero at equally spaced chosen roots of unity in
    79→ * the domain of size `FIELD_ELEMENTS_PER_BLOB`.
    80→ *
    81→ * The roots of unity are chosen based on the missing cell indices. If the i'th cell is missing,
    82→ * then the i'th root of unity from `roots_of_unity` will be zero on the polynomial
    83→ * computed, along with every `CELLS_PER_EXT_BLOB` spaced root of unity in the domain.
    84→ *
    85→ * @param[in,out]   vanishing_poly          The output vanishing polynomial
    86→ * @param[in]       missing_cell_indices    The array of missing cell indices
    87→ * @param[in]       len_missing_cells       The number of missing cell indices
    88→ * @param[in]       s                       The trusted setup
    89→ *
    90→ * @remark If no cells are missing, recovery is trivial; we expect the caller to handle this.
    91→ * @remark If all cells are missing, we return C_KZG_BADARGS; the algorithm has an edge case.
    92→ */
    93→static C_KZG_RET vanishing_polynomial_for_missing_cells(
    94→    fr_t *vanishing_poly,
    95→    const uint64_t *missing_cell_indices,
    96→    size_t len_missing_cells,
    97→    const KZGSettings *s
    98→) {
    99→    C_KZG_RET ret;
   100→    fr_t *roots = NULL;
   101→    fr_t *short_vanishing_poly = NULL;
   102→    size_t short_vanishing_poly_len = 0;
   103→
   104→    /* Return early if none or all of the cells are missing */
   105→    if (len_missing_cells == 0 || len_missing_cells >= CELLS_PER_EXT_BLOB) {
   106→        ret = C_KZG_BADARGS;
   107→        goto out;
   108→    }
   109→
   110→    /* Allocate arrays */
   111→    ret = new_fr_array(&roots, len_missing_cells);
   112→    if (ret != C_KZG_OK) goto out;
   113→    ret = new_fr_array(&short_vanishing_poly, (len_missing_cells + 1));
   114→    if (ret != C_KZG_OK) goto out;
   115→
   116→    /*
   117→     * For each missing cell index, choose the corresponding root of unity from the subgroup of
   118→     * size `CELLS_PER_EXT_BLOB`.
   119→     *
   120→     * In other words, if the missing index is `i`, then we add \omega^i to the roots array, where
   121→     * \omega is a primitive `CELLS_PER_EXT_BLOB` root of unity.
   122→     */
   123→    size_t stride = FIELD_ELEMENTS_PER_EXT_BLOB / CELLS_PER_EXT_BLOB;
   124→    for (size_t i = 0; i < len_missing_cells; i++) {
   125→        roots[i] = s->roots_of_unity[missing_cell_indices[i] * stride];
   126→    }
   127→
   128→    /* Compute the polynomial that evaluates to zero on the roots */
   129→    ret = compute_vanishing_polynomial_from_roots(
   130→        short_vanishing_poly, &short_vanishing_poly_len, roots, len_missing_cells
   131→    );
   132→    if (ret != C_KZG_OK) goto out;
   133→
   134→    /* Zero out all the coefficients of the output poly */
   135→    for (size_t i = 0; i < FIELD_ELEMENTS_PER_EXT_BLOB; i++) {
   136→        vanishing_poly[i] = FR_ZERO;
   137→    }
   138→
   139→    /*
   140→     * For each root \omega^i in `short_vanishing_poly`, we compute a polynomial that has roots at
   141→     *
   142→     *  H = {
   143→     *      \omega^i * \gamma^0,
   144→     *      \omega^i * \gamma^1,
   145→     *      ...,
   146→     *      \omega^i * \gamma^{FIELD_ELEMENTS_PER_CELL-1}
   147→     *  }
   148→     *
   149→     * where \gamma is a primitive `FIELD_ELEMENTS_PER_EXT_BLOB`-th root of unity.
   150→     *
   151→     * This is done by shifting the degree of all coefficients in `short_vanishing_poly` up by
   152→     * `FIELD_ELEMENTS_PER_CELL` amount.
   153→     */
   154→    for (size_t i = 0; i < short_vanishing_poly_len; i++) {
   155→        vanishing_poly[i * FIELD_ELEMENTS_PER_CELL] = short_vanishing_poly[i];
   156→    }
   157→
   158→out:
   159→    c_kzg_free(roots);
   160→    c_kzg_free(short_vanishing_poly);
   161→    return ret;
   162→}
