   164→////////////////////////////////////////////////////////////////////////////////////////////////////
   165→// Cell Recovery
   166→////////////////////////////////////////////////////////////////////////////////////////////////////
   167→
   168→/**
   169→ * Helper function to check if a uint64 value is in an array.
   170→ *
   171→ * @param[in]   arr         The array
   172→ * @param[in]   arr_size    The size of the array
   173→ * @param[in]   value       The value we want to search
   174→ *
   175→ * @return True if the value is in the array, otherwise false.
   176→ */
   177→static bool is_in_array(const uint64_t *arr, size_t arr_size, uint64_t value) {
   178→    for (size_t i = 0; i < arr_size; i++) {
   179→        if (arr[i] == value) {
   180→            return true;
   181→        }
   182→    }
   183→    return false;
   184→}
   185→
   186→/**
   187→ * Given a set of cells with up to half the entries missing, return the reconstructed
   188→ * original. Assumes that the inverse FFT of the original data has the upper half of its values
   189→ * equal to zero.
   190→ *
   191→ * @param[out]  reconstructed_data_out  Array of size FIELD_ELEMENTS_PER_EXT_BLOB to recover cells
   192→ * @param[in]   cell_indices            An array with the available cell indices, length `num_cells`
   193→ * @param[in]   num_cells               The size of the `cell_indices` array
   194→ * @param[in]   cells                   An array of size FIELD_ELEMENTS_PER_EXT_BLOB with the cells
   195→ * @param[in]   s                       The trusted setup
   196→ *
   197→ * @remark `reconstructed_data_out` and `cells` can point to the same memory.
   198→ * @remark The array `cells` must be in the correct order (according to cell_indices).
   199→ * @remark Missing cells in `cells` should be equal to FR_NULL.
   200→ */
   201→C_KZG_RET recover_cells(
   202→    fr_t *reconstructed_data_out,
   203→    const uint64_t *cell_indices,
   204→    size_t num_cells,
   205→    fr_t *cells,
   206→    const KZGSettings *s
   207→) {
   208→    C_KZG_RET ret;
   209→    uint64_t *missing_cell_indices = NULL;
   210→    fr_t *vanishing_poly_eval = NULL;
   211→    fr_t *vanishing_poly_coeff = NULL;
   212→    fr_t *extended_evaluation_times_zero = NULL;
   213→    fr_t *extended_evaluation_times_zero_coeffs = NULL;
   214→    fr_t *extended_evaluations_over_coset = NULL;
   215→    fr_t *vanishing_poly_over_coset = NULL;
   216→    fr_t *reconstructed_poly_coeff = NULL;
   217→    fr_t *cells_brp = NULL;
   218→
   219→    /* Allocate space for arrays */
   220→    ret = c_kzg_calloc(
   221→        (void **)&missing_cell_indices, FIELD_ELEMENTS_PER_EXT_BLOB, sizeof(uint64_t)
   222→    );
   223→    if (ret != C_KZG_OK) goto out;
   224→    ret = new_fr_array(&vanishing_poly_eval, FIELD_ELEMENTS_PER_EXT_BLOB);
   225→    if (ret != C_KZG_OK) goto out;
   226→    ret = new_fr_array(&vanishing_poly_coeff, FIELD_ELEMENTS_PER_EXT_BLOB);
   227→    if (ret != C_KZG_OK) goto out;
   228→    ret = new_fr_array(&extended_evaluation_times_zero, FIELD_ELEMENTS_PER_EXT_BLOB);
   229→    if (ret != C_KZG_OK) goto out;
   230→    ret = new_fr_array(&extended_evaluation_times_zero_coeffs, FIELD_ELEMENTS_PER_EXT_BLOB);
   231→    if (ret != C_KZG_OK) goto out;
   232→    ret = new_fr_array(&extended_evaluations_over_coset, FIELD_ELEMENTS_PER_EXT_BLOB);
   233→    if (ret != C_KZG_OK) goto out;
   234→    ret = new_fr_array(&vanishing_poly_over_coset, FIELD_ELEMENTS_PER_EXT_BLOB);
   235→    if (ret != C_KZG_OK) goto out;
   236→    ret = new_fr_array(&reconstructed_poly_coeff, FIELD_ELEMENTS_PER_EXT_BLOB);
   237→    if (ret != C_KZG_OK) goto out;
   238→    ret = new_fr_array(&cells_brp, FIELD_ELEMENTS_PER_EXT_BLOB);
   239→    if (ret != C_KZG_OK) goto out;
   240→
   241→    /* Bit-reverse the data points, stored in new array */
   242→    memcpy(cells_brp, cells, FIELD_ELEMENTS_PER_EXT_BLOB * sizeof(fr_t));
   243→    ret = bit_reversal_permutation(cells_brp, sizeof(fr_t), FIELD_ELEMENTS_PER_EXT_BLOB);
   244→    if (ret != C_KZG_OK) goto out;
   245→
   246→    /* Identify missing cells */
   247→    size_t len_missing = 0;
   248→    for (size_t i = 0; i < CELLS_PER_EXT_BLOB; i++) {
   249→        /* Iterate over each cell index and check if we have received it */
   250→        if (!is_in_array(cell_indices, num_cells, i)) {
   251→            /* If the cell is missing, bit reverse the index and add it to the missing array */
   252→            uint64_t brp_i = reverse_bits_limited(CELLS_PER_EXT_BLOB, i);
   253→            missing_cell_indices[len_missing++] = brp_i;
   254→        }
   255→    }
   256→
   257→    /*
   258→     * Check that we have enough cells to recover.
   259→     * Concretely, we need to have at least CELLS_PER_BLOB many cells.
   260→     */
   261→    assert(CELLS_PER_EXT_BLOB - len_missing >= CELLS_PER_BLOB);
   262→
   263→    /*
   264→     * Compute Z(x) in monomial form.
   265→     * Z(x) is the polynomial which vanishes on all of the evaluations which are missing.
   266→     */
   267→    ret = vanishing_polynomial_for_missing_cells(
   268→        vanishing_poly_coeff, missing_cell_indices, len_missing, s
   269→    );
   270→    if (ret != C_KZG_OK) goto out;
   271→
   272→    /* Convert Z(x) to evaluation form */
   273→    ret = fr_fft(vanishing_poly_eval, vanishing_poly_coeff, FIELD_ELEMENTS_PER_EXT_BLOB, s);
   274→    if (ret != C_KZG_OK) goto out;
   275→
   276→    /*
   277→     * Compute (E*Z)(x) = E(x) * Z(x) in evaluation form over the FFT domain.
   278→     *
   279→     * Note: over the FFT domain, the polynomials (E*Z)(x) and (P*Z)(x) agree, where
   280→     * P(x) is the polynomial we want to reconstruct (degree FIELD_ELEMENTS_PER_BLOB - 1).
   281→     */
   282→    for (size_t i = 0; i < FIELD_ELEMENTS_PER_EXT_BLOB; i++) {
   283→        if (fr_is_null(&cells_brp[i])) {
   284→            /*
   285→             * We handle this situation differently because FR_NULL is an invalid value. The right
   286→             * hand side, vanishing_poly_eval[i], will always be zero when cells_brp[i] is null, so
   287→             * the multiplication would still be result in zero, but we shouldn't depend on blst
   288→             * handling invalid values like this.
   289→             */
   290→            extended_evaluation_times_zero[i] = FR_ZERO;
   291→        } else {
   292→            blst_fr_mul(&extended_evaluation_times_zero[i], &cells_brp[i], &vanishing_poly_eval[i]);
   293→        }
   294→    }
   295→
   296→    /*
   297→     * Convert (E*Z)(x) to monomial form.
   298→     *
   299→     * We know that (E*Z)(x) and (P*Z)(x) agree over the FFT domain,
   300→     * and we know that (P*Z)(x) has degree at most FIELD_ELEMENTS_PER_EXT_BLOB - 1.
   301→     * Thus, an inverse FFT of the evaluations of (E*Z)(x) (= evaluations of (P*Z)(x))
   302→     * yields the coefficient form of (P*Z)(x).
   303→     */
   304→    ret = fr_ifft(
   305→        extended_evaluation_times_zero_coeffs,
   306→        extended_evaluation_times_zero,
   307→        FIELD_ELEMENTS_PER_EXT_BLOB,
   308→        s
   309→    );
   310→    if (ret != C_KZG_OK) goto out;
   311→
   312→    /*
   313→     * Next step is to divide the polynomial (P*Z)(x) by polynomial Z(x) to get P(x).
   314→     * We do this in evaluation form over a coset of the FFT domain to avoid division by 0.
   315→     *
   316→     * Convert (P*Z)(x) to evaluation form over a coset of the FFT domain.
   317→     */
   318→    ret = coset_fft(
   319→        extended_evaluations_over_coset,
   320→        extended_evaluation_times_zero_coeffs,
   321→        FIELD_ELEMENTS_PER_EXT_BLOB,
   322→        s
   323→    );
   324→    if (ret != C_KZG_OK) goto out;
   325→
   326→    /* Convert Z(x) to evaluation form over a coset of the FFT domain */
   327→    ret = coset_fft(
   328→        vanishing_poly_over_coset, vanishing_poly_coeff, FIELD_ELEMENTS_PER_EXT_BLOB, s
   329→    );
   330→    if (ret != C_KZG_OK) goto out;
   331→
   332→    /* Compute P(x) = (P*Z)(x) / Z(x) in evaluation form over a coset of the FFT domain */
   333→    for (size_t i = 0; i < FIELD_ELEMENTS_PER_EXT_BLOB; i++) {
   334→        fr_div(
   335→            &extended_evaluations_over_coset[i],
   336→            &extended_evaluations_over_coset[i],
   337→            &vanishing_poly_over_coset[i]
   338→        );
   339→    }
   340→
   341→    /*
   342→     * Note: After the above polynomial division, extended_evaluations_over_coset is the same
   343→     * polynomial as reconstructed_poly_over_coset in the spec.
   344→     */
   345→
   346→    /* Convert P(x) to coefficient form */
   347→    ret = coset_ifft(
   348→        reconstructed_poly_coeff, extended_evaluations_over_coset, FIELD_ELEMENTS_PER_EXT_BLOB, s
   349→    );
   350→    if (ret != C_KZG_OK) goto out;
   351→
   352→    /*
   353→     * After unscaling the reconstructed polynomial, we have P(x) which evaluates to our original
   354→     * data at the roots of unity. Next, we evaluate the polynomial to get the original data.
   355→     */
   356→    ret = fr_fft(reconstructed_data_out, reconstructed_poly_coeff, FIELD_ELEMENTS_PER_EXT_BLOB, s);
   357→    if (ret != C_KZG_OK) goto out;
   358→
   359→    /* Bit-reverse the recovered data points */
   360→    ret = bit_reversal_permutation(
   361→        reconstructed_data_out, sizeof(fr_t), FIELD_ELEMENTS_PER_EXT_BLOB
   362→    );
   363→    if (ret != C_KZG_OK) goto out;
   364→
   365→out:
   366→    c_kzg_free(missing_cell_indices);
   367→    c_kzg_free(vanishing_poly_eval);
   368→    c_kzg_free(extended_evaluation_times_zero);
   369→    c_kzg_free(extended_evaluation_times_zero_coeffs);
   370→    c_kzg_free(extended_evaluations_over_coset);
   371→    c_kzg_free(vanishing_poly_over_coset);
   372→    c_kzg_free(reconstructed_poly_coeff);
   373→    c_kzg_free(vanishing_poly_coeff);
   374→    c_kzg_free(cells_brp);
   375→    return ret;
   376→}
