    69→/**
    70→ * Given a blob, compute all of its cells and proofs.
    71→ *
    72→ * @param[out]  cells   An array of CELLS_PER_EXT_BLOB cells
    73→ * @param[out]  proofs  An array of CELLS_PER_EXT_BLOB proofs
    74→ * @param[in]   blob    The blob to get cells/proofs for
    75→ * @param[in]   s       The trusted setup
    76→ *
    77→ * @remark If cells is NULL, they won't be computed.
    78→ * @remark If proofs is NULL, they won't be computed.
    79→ * @remark Will return an error if both cells & proofs are NULL.
    80→ */
    81→C_KZG_RET compute_cells_and_kzg_proofs(
    82→    Cell *cells, KZGProof *proofs, const Blob *blob, const KZGSettings *s
    83→) {
    84→    C_KZG_RET ret;
    85→    fr_t *poly_monomial = NULL;
    86→    fr_t *poly_lagrange = NULL;
    87→    fr_t *data_fr = NULL;
    88→    g1_t *proofs_g1 = NULL;
    89→
    90→    /* If both of these are null, something is wrong */
    91→    if (cells == NULL && proofs == NULL) {
    92→        return C_KZG_BADARGS;
    93→    }
    94→
    95→    /* Allocate space fr-form arrays */
    96→    ret = new_fr_array(&poly_monomial, FIELD_ELEMENTS_PER_EXT_BLOB);
    97→    if (ret != C_KZG_OK) goto out;
    98→    ret = new_fr_array(&poly_lagrange, FIELD_ELEMENTS_PER_EXT_BLOB);
    99→    if (ret != C_KZG_OK) goto out;
   100→
   101→    /*
   102→     * Convert the blob to a polynomial in lagrange form. Note that only the first 4096 fields of
   103→     * the polynomial will be set. The upper 4096 fields will remain zero. The extra space is
   104→     * required because the polynomial will be evaluated to the extended domain (8192 roots of
   105→     * unity).
   106→     */
   107→    ret = blob_to_polynomial(poly_lagrange, blob);
   108→    if (ret != C_KZG_OK) goto out;
   109→
   110→    /* We need the polynomial to be in monomial form */
   111→    ret = poly_lagrange_to_monomial(poly_monomial, poly_lagrange, FIELD_ELEMENTS_PER_BLOB, s);
   112→    if (ret != C_KZG_OK) goto out;
   113→
   114→    /* Ensure that only the first FIELD_ELEMENTS_PER_BLOB elements can be non-zero */
   115→    for (size_t i = FIELD_ELEMENTS_PER_BLOB; i < FIELD_ELEMENTS_PER_EXT_BLOB; i++) {
   116→        assert(fr_equal(&poly_monomial[i], &FR_ZERO));
   117→    }
   118→
   119→    if (cells != NULL) {
   120→        /* Allocate space for our data points */
   121→        ret = new_fr_array(&data_fr, FIELD_ELEMENTS_PER_EXT_BLOB);
   122→        if (ret != C_KZG_OK) goto out;
   123→
   124→        /* Get the data points via forward transformation */
   125→        ret = fr_fft(data_fr, poly_monomial, FIELD_ELEMENTS_PER_EXT_BLOB, s);
   126→        if (ret != C_KZG_OK) goto out;
   127→
   128→        /* Bit-reverse the data points */
   129→        ret = bit_reversal_permutation(data_fr, sizeof(fr_t), FIELD_ELEMENTS_PER_EXT_BLOB);
   130→        if (ret != C_KZG_OK) goto out;
   131→
   132→        /* Convert all of the cells to byte-form */
   133→        for (size_t i = 0; i < CELLS_PER_EXT_BLOB; i++) {
   134→            for (size_t j = 0; j < FIELD_ELEMENTS_PER_CELL; j++) {
   135→                size_t index = i * FIELD_ELEMENTS_PER_CELL + j;
   136→                size_t offset = j * BYTES_PER_FIELD_ELEMENT;
   137→                bytes_from_bls_field((Bytes32 *)&cells[i].bytes[offset], &data_fr[index]);
   138→            }
   139→        }
   140→    }
   141→
   142→    if (proofs != NULL) {
   143→        /* Allocate space for our proofs in g1-form */
   144→        ret = new_g1_array(&proofs_g1, CELLS_PER_EXT_BLOB);
   145→        if (ret != C_KZG_OK) goto out;
   146→
   147→        /* Compute the proofs, only uses the first half of the polynomial */
   148→        ret = compute_fk20_cell_proofs(proofs_g1, poly_monomial, s);
   149→        if (ret != C_KZG_OK) goto out;
   150→
   151→        /* Bit-reverse the proofs */
   152→        ret = bit_reversal_permutation(proofs_g1, sizeof(g1_t), CELLS_PER_EXT_BLOB);
   153→        if (ret != C_KZG_OK) goto out;
   154→
   155→        /* Convert all of the proofs to byte-form */
   156→        for (size_t i = 0; i < CELLS_PER_EXT_BLOB; i++) {
   157→            bytes_from_g1(&proofs[i], &proofs_g1[i]);
   158→        }
   159→    }
   160→
   161→out:
   162→    c_kzg_free(poly_monomial);
   163→    c_kzg_free(poly_lagrange);
   164→    c_kzg_free(data_fr);
   165→    c_kzg_free(proofs_g1);
   166→    return ret;
   167→}
