   169→////////////////////////////////////////////////////////////////////////////////////////////////////
   170→// Recover
   171→////////////////////////////////////////////////////////////////////////////////////////////////////
   172→
   173→/**
   174→ * Given some cells for a blob, recover all cells/proofs.
   175→ *
   176→ * @param[out]  recovered_cells     An array of CELLS_PER_EXT_BLOB cells
   177→ * @param[out]  recovered_proofs    An array of CELLS_PER_EXT_BLOB proofs
   178→ * @param[in]   cell_indices        The cell indices for the available cells, length `num_cells`
   179→ * @param[in]   cells               The available cells we recover from, length `num_cells`
   180→ * @param[in]   num_cells           The number of available cells provided
   181→ * @param[in]   s                   The trusted setup
   182→ *
   183→ * @remark At least CELLS_PER_BLOB cells must be provided.
   184→ * @remark Recovery is faster if there are fewer missing cells.
   185→ * @remark If recovered_proofs is NULL, they will not be recomputed.
   186→ */
   187→C_KZG_RET recover_cells_and_kzg_proofs(
   188→    Cell *recovered_cells,
   189→    KZGProof *recovered_proofs,
   190→    const uint64_t *cell_indices,
   191→    const Cell *cells,
   192→    uint64_t num_cells,
   193→    const KZGSettings *s
   194→) {
   195→    C_KZG_RET ret;
   196→    fr_t *recovered_cells_fr = NULL;
   197→    g1_t *recovered_proofs_g1 = NULL;
   198→
   199→    /* Ensure only one blob's worth of cells was provided */
   200→    if (num_cells > CELLS_PER_EXT_BLOB) {
   201→        ret = C_KZG_BADARGS;
   202→        goto out;
   203→    }
   204→
   205→    /* Check if it's possible to recover */
   206→    if (num_cells < CELLS_PER_BLOB) {
   207→        ret = C_KZG_BADARGS;
   208→        goto out;
   209→    }
   210→
   211→    /* Check that cell indices are valid */
   212→    for (size_t i = 0; i < num_cells; i++) {
   213→        if (cell_indices[i] >= CELLS_PER_EXT_BLOB) {
   214→            ret = C_KZG_BADARGS;
   215→            goto out;
   216→        }
   217→    }
   218→
   219→    /* Do allocations */
   220→    ret = new_fr_array(&recovered_cells_fr, FIELD_ELEMENTS_PER_EXT_BLOB);
   221→    if (ret != C_KZG_OK) goto out;
   222→    ret = new_g1_array(&recovered_proofs_g1, CELLS_PER_EXT_BLOB);
   223→    if (ret != C_KZG_OK) goto out;
   224→
   225→    /* Initialize all cells as missing */
   226→    for (size_t i = 0; i < FIELD_ELEMENTS_PER_EXT_BLOB; i++) {
   227→        recovered_cells_fr[i] = FR_NULL;
   228→    }
   229→
   230→    /* Populate recovered_cells_fr with available cells at the right places */
   231→    for (size_t i = 0; i < num_cells; i++) {
   232→        size_t index = cell_indices[i] * FIELD_ELEMENTS_PER_CELL;
   233→        for (size_t j = 0; j < FIELD_ELEMENTS_PER_CELL; j++) {
   234→            fr_t *ptr = &recovered_cells_fr[index + j];
   235→
   236→            /*
   237→             * Check if the field has already been set. If it has, there was a duplicate cell index
   238→             * and we can return an error. The compiler will optimize this and the overhead is
   239→             * practically zero.
   240→             */
   241→            if (!fr_is_null(ptr)) {
   242→                ret = C_KZG_BADARGS;
   243→                goto out;
   244→            }
   245→
   246→            /* Convert the untrusted input bytes to a field element */
   247→            size_t offset = j * BYTES_PER_FIELD_ELEMENT;
   248→            ret = bytes_to_bls_field(ptr, (const Bytes32 *)&cells[i].bytes[offset]);
   249→            if (ret != C_KZG_OK) goto out;
   250→        }
   251→    }
   252→
   253→    if (num_cells == CELLS_PER_EXT_BLOB) {
   254→        /* Nothing to recover, copy the cells */
   255→        memcpy(recovered_cells, cells, CELLS_PER_EXT_BLOB * sizeof(Cell));
   256→    } else {
   257→        /* Perform cell recovery */
   258→        ret = recover_cells(recovered_cells_fr, cell_indices, num_cells, recovered_cells_fr, s);
   259→        if (ret != C_KZG_OK) goto out;
   260→
   261→        /* Convert the recovered data points to byte-form */
   262→        for (size_t i = 0; i < CELLS_PER_EXT_BLOB; i++) {
   263→            for (size_t j = 0; j < FIELD_ELEMENTS_PER_CELL; j++) {
   264→                size_t index = i * FIELD_ELEMENTS_PER_CELL + j;
   265→                size_t offset = j * BYTES_PER_FIELD_ELEMENT;
   266→                bytes_from_bls_field(
   267→                    (Bytes32 *)&recovered_cells[i].bytes[offset], &recovered_cells_fr[index]
   268→                );
   269→            }
   270→        }
   271→    }
   272→
   273→    if (recovered_proofs != NULL) {
   274→        /*
   275→         * Instead of converting the cells to a blob and back, we can just treat the cells as a
   276→         * polynomial. We are done with the fr-form recovered cells and we can safely mutate the
   277→         * array.
   278→         */
   279→        ret = poly_lagrange_to_monomial(
   280→            recovered_cells_fr, recovered_cells_fr, FIELD_ELEMENTS_PER_EXT_BLOB, s
   281→        );
   282→        if (ret != C_KZG_OK) goto out;
   283→
   284→        /* Compute the proofs, only uses the first half of the polynomial */
   285→        ret = compute_fk20_cell_proofs(recovered_proofs_g1, recovered_cells_fr, s);
   286→        if (ret != C_KZG_OK) goto out;
   287→
   288→        /* Bit-reverse the proofs */
   289→        ret = bit_reversal_permutation(recovered_proofs_g1, sizeof(g1_t), CELLS_PER_EXT_BLOB);
   290→        if (ret != C_KZG_OK) goto out;
   291→
   292→        /* Convert all of the proofs to byte-form */
   293→        for (size_t i = 0; i < CELLS_PER_EXT_BLOB; i++) {
   294→            bytes_from_g1(&recovered_proofs[i], &recovered_proofs_g1[i]);
   295→        }
   296→    }
   297→
   298→out:
   299→    c_kzg_free(recovered_cells_fr);
   300→    c_kzg_free(recovered_proofs_g1);
   301→    return ret;
   302→}
