   304→////////////////////////////////////////////////////////////////////////////////////////////////////
   305→// Verify
   306→////////////////////////////////////////////////////////////////////////////////////////////////////
   307→
   308→/**
   309→ * Helper function to compare two commitments.
   310→ *
   311→ * @param[in]   a   The first commitment
   312→ * @param[in]   b   The second commitment
   313→ *
   314→ * @return True if the commitments are the same, otherwise false.
   315→ */
   316→static bool commitments_equal(const Bytes48 *a, const Bytes48 *b) {
   317→    return memcmp(a->bytes, b->bytes, BYTES_PER_COMMITMENT) == 0;
   318→}
   319→
   320→/**
   321→ * Helper function to copy one commitment's bytes to another.
   322→ *
   323→ * @param[in]   dst The destination commitment
   324→ * @param[in]   src The source commitment
   325→ */
   326→static void commitments_copy(Bytes48 *dst, const Bytes48 *src) {
   327→    memcpy(dst->bytes, src->bytes, BYTES_PER_COMMITMENT);
   328→}
   329→
   330→/**
   331→ * Convert a list of commitments with potential duplicates to a list of unique commitments. Also
   332→ * returns a list of indices which point to those new unique commitments.
   333→ *
   334→ * @param[in,out]   commitments_out Updated to only contain unique commitments
   335→ * @param[out]      indices_out     Used as map between old/new commitments
   336→ * @param[in,out]   count_out       Number of commitments before and after
   337→ *
   338→ * @remark The input arrays are re-used.
   339→ * @remark The number of commitments/indices must be the same.
   340→ * @remark The length of `indices_out` is unchanged.
   341→ * @remark `count_out` is updated to be the number of unique commitments.
   342→ */
   343→static void deduplicate_commitments(
   344→    Bytes48 *commitments_out, uint64_t *indices_out, size_t *count_out
   345→) {
   346→    /* Bail early if there are no commitments */
   347→    if (*count_out == 0) return;
   348→
   349→    /* The first commitment is always new */
   350→    indices_out[0] = 0;
   351→    size_t new_count = 1;
   352→
   353→    /* Create list of unique commitments & indices to them */
   354→    for (size_t i = 1; i < *count_out; i++) {
   355→        bool exist = false;
   356→        for (size_t j = 0; j < new_count; j++) {
   357→            if (commitments_equal(&commitments_out[i], &commitments_out[j])) {
   358→                /* This commitment already exists */
   359→                indices_out[i] = j;
   360→                exist = true;
   361→                break;
   362→            }
   363→        }
   364→        if (!exist) {
   365→            /* This is a new commitment */
   366→            commitments_copy(&commitments_out[new_count], &commitments_out[i]);
   367→            indices_out[i] = new_count;
   368→            new_count++;
   369→        }
   370→    }
   371→
   372→    /* Update the count */
   373→    *count_out = new_count;
   374→}
   375→
   376→/**
   377→ * Compute random linear combination challenge scalars for verify_cell_kzg_proof_batch. In this, we
   378→ * must hash EVERYTHING that the prover can control.
   379→ *
   380→ * @param[out]  r_powers_out        The output challenges, length `num_cells`
   381→ * @param[in]   commitments_bytes   The input commitments, length `num_commitments`
   382→ * @param[in]   num_commitments     The number of commitments
   383→ * @param[in]   commitment_indices  The cell commitment indices, length `num_cells`
   384→ * @param[in]   cell_indices        The cell indices, length `num_cells`
   385→ * @param[in]   cells               The cell, length `num_cells`
   386→ * @param[in]   proofs_bytes        The cell proof, length `num_cells`
   387→ * @param[in]   num_cells           The number of cells
   388→ */
   389→static C_KZG_RET compute_r_powers_for_verify_cell_kzg_proof_batch(
   390→    fr_t *r_powers_out,
   391→    const Bytes48 *commitments_bytes,
   392→    size_t num_commitments,
   393→    const uint64_t *commitment_indices,
   394→    const uint64_t *cell_indices,
   395→    const Cell *cells,
   396→    const Bytes48 *proofs_bytes,
   397→    uint64_t num_cells
   398→) {
   399→    C_KZG_RET ret;
   400→    uint8_t *bytes = NULL;
   401→    Bytes32 r_bytes;
   402→    fr_t r;
   403→
   404→    /* Calculate the size of the data we're going to hash */
   405→    size_t input_size = DOMAIN_STR_LENGTH                          /* The domain separator */
   406→                        + sizeof(uint64_t)                         /* FIELD_ELEMENTS_PER_CELL */
   407→                        + sizeof(uint64_t)                         /* num_commitments */
   408→                        + sizeof(uint64_t)                         /* num_cells */
   409→                        + (num_commitments * BYTES_PER_COMMITMENT) /* commitment_bytes */
   410→                        + (num_cells * sizeof(uint64_t))           /* commitment_indices */
   411→                        + (num_cells * sizeof(uint64_t))           /* cell_indices */
   412→                        + (num_cells * BYTES_PER_CELL)             /* cells */
   413→                        + (num_cells * BYTES_PER_PROOF);           /* proofs_bytes */
   414→
   415→    /* Allocate space to copy this data into */
   416→    ret = c_kzg_malloc((void **)&bytes, input_size);
   417→    if (ret != C_KZG_OK) goto out;
   418→
   419→    /* Pointer tracking `bytes` for writing on top of it */
   420→    uint8_t *offset = bytes;
   421→
   422→    /* Ensure that the domain string is the correct length */
   423→    assert(strlen(RANDOM_CHALLENGE_DOMAIN_VERIFY_CELL_KZG_PROOF_BATCH) == DOMAIN_STR_LENGTH);
   424→
   425→    /* Copy domain separator */
   426→    memcpy(offset, RANDOM_CHALLENGE_DOMAIN_VERIFY_CELL_KZG_PROOF_BATCH, DOMAIN_STR_LENGTH);
   427→    offset += DOMAIN_STR_LENGTH;
   428→
   429→    /* Copy field elements per cell */
   430→    bytes_from_uint64(offset, FIELD_ELEMENTS_PER_CELL);
   431→    offset += sizeof(uint64_t);
   432→
   433→    /* Copy number of commitments */
   434→    bytes_from_uint64(offset, num_commitments);
   435→    offset += sizeof(uint64_t);
   436→
   437→    /* Copy number of cells */
   438→    bytes_from_uint64(offset, num_cells);
   439→    offset += sizeof(uint64_t);
   440→
   441→    for (size_t i = 0; i < num_commitments; i++) {
   442→        /* Copy commitment */
   443→        memcpy(offset, &commitments_bytes[i], BYTES_PER_COMMITMENT);
   444→        offset += BYTES_PER_COMMITMENT;
   445→    }
   446→
   447→    for (size_t i = 0; i < num_cells; i++) {
   448→        /* Copy row id */
   449→        bytes_from_uint64(offset, commitment_indices[i]);
   450→        offset += sizeof(uint64_t);
   451→
   452→        /* Copy column id */
   453→        bytes_from_uint64(offset, cell_indices[i]);
   454→        offset += sizeof(uint64_t);
   455→
   456→        /* Copy cell */
   457→        memcpy(offset, &cells[i], BYTES_PER_CELL);
   458→        offset += BYTES_PER_CELL;
   459→
   460→        /* Copy proof */
   461→        memcpy(offset, &proofs_bytes[i], BYTES_PER_PROOF);
   462→        offset += BYTES_PER_PROOF;
   463→    }
   464→
   465→    /* Now let's create the challenge! */
   466→    blst_sha256(r_bytes.bytes, bytes, input_size);
   467→    hash_to_bls_field(&r, &r_bytes);
   468→
   469→    /* Raise power of r for each cell */
   470→    compute_powers(r_powers_out, &r, num_cells);
   471→
   472→    /* Make sure we wrote the entire buffer */
   473→    assert(offset == bytes + input_size);
   474→
   475→out:
   476→    c_kzg_free(bytes);
   477→    return ret;
   478→}
   479→
   480→/**
   481→ * Compute the sum of the commitments weighted by the powers of r.
   482→ *
   483→ * @param[out]  sum_of_commitments_out  The resulting G1 sum of the commitments
   484→ * @param[in]   unique_commitments      Array of unique commitments, length `num_commitments`
   485→ * @param[in]   commitment_indices      Indices mapping to unique commitments, length `num_cells`
   486→ * @param[in]   r_powers                Array of powers of r used for weighting, length `num_cells`
   487→ * @param[in]   num_commitments         The number of unique commitments
   488→ * @param[in]   num_cells               The number of cells
   489→ */
   490→static C_KZG_RET compute_weighted_sum_of_commitments(
   491→    g1_t *sum_of_commitments_out,
   492→    const Bytes48 *unique_commitments,
   493→    const uint64_t *commitment_indices,
   494→    const fr_t *r_powers,
   495→    size_t num_commitments,
   496→    uint64_t num_cells
   497→) {
   498→    C_KZG_RET ret;
   499→    g1_t *commitments_g1 = NULL;
   500→    fr_t *commitment_weights = NULL;
   501→
   502→    ret = new_fr_array(&commitment_weights, num_commitments);
   503→    if (ret != C_KZG_OK) goto out;
   504→    ret = new_g1_array(&commitments_g1, num_commitments);
   505→    if (ret != C_KZG_OK) goto out;
   506→
   507→    for (size_t i = 0; i < num_commitments; i++) {
   508→        /* Convert & validate commitment */
   509→        ret = bytes_to_kzg_commitment(&commitments_g1[i], &unique_commitments[i]);
   510→        if (ret != C_KZG_OK) goto out;
   511→
   512→        /* Initialize the weight to zero */
   513→        commitment_weights[i] = FR_ZERO;
   514→    }
   515→
   516→    /* Update commitment weights */
   517→    for (uint64_t i = 0; i < num_cells; i++) {
   518→        blst_fr_add(
   519→            &commitment_weights[commitment_indices[i]],
   520→            &commitment_weights[commitment_indices[i]],
   521→            &r_powers[i]
   522→        );
   523→    }
   524→
   525→    /* Compute commitment sum */
   526→    ret = g1_lincomb_fast(
   527→        sum_of_commitments_out, commitments_g1, commitment_weights, num_commitments
   528→    );
   529→    if (ret != C_KZG_OK) goto out;
   530→
   531→out:
   532→    c_kzg_free(commitment_weights);
   533→    c_kzg_free(commitments_g1);
   534→    return ret;
   535→}
   536→
   537→/**
   538→ * Compute the inverse coset factor h_k^{-1},
   539→ *  where `h_k` is the coset factor for cell with index `k`.
   540→ *
   541→ * @param[out]  inv_coset_factor_out    Pointer to store the computed inverse coset factor
   542→ * @param[in]   cell_index              The index of the cell
   543→ * @param[in]   s                       The trusted setup
   544→ */
   545→static void get_inv_coset_shift_for_cell(
   546→    fr_t *inv_coset_factor_out, uint64_t cell_index, const KZGSettings *s
   547→) {
   548→    /*
   549→     * Get the cell index in reverse-bit order.
   550→     * This index points to this cell's coset factor h_k in the roots_of_unity array.
   551→     */
   552→    uint64_t cell_idx_rbl = CELL_INDICES_RBL[cell_index];
   553→
   554→    /*
   555→     * Observe that for every element in roots_of_unity, we can find its inverse by
   556→     * accessing its reflected element.
   557→     *
   558→     * For example, consider a multiplicative subgroup with eight elements:
   559→     *   roots = {w^0, w^1, w^2, ... w^7, w^0}
   560→     * For a root of unity in roots[i], we can find its inverse in roots[-i].
   561→     */
   562→    assert(cell_idx_rbl <= FIELD_ELEMENTS_PER_EXT_BLOB);
   563→    uint64_t inv_coset_factor_idx = FIELD_ELEMENTS_PER_EXT_BLOB - cell_idx_rbl;
   564→
   565→    /* Get h_k^{-1} using the index */
   566→    assert(inv_coset_factor_idx < FIELD_ELEMENTS_PER_EXT_BLOB + 1);
   567→    *inv_coset_factor_out = s->roots_of_unity[inv_coset_factor_idx];
   568→}
   569→
   570→/**
   571→ * Compute h_k^{n}, where `h_k` is the coset factor for cell with index `k`.
   572→ *
   573→ * @param[out]  coset_factor_out    Pointer to store h_k^{n}
   574→ * @param[in]   cell_index          The index of the cell
   575→ * @param[in]   s                   The trusted setup
   576→ */
   577→static void get_coset_shift_pow_for_cell(
   578→    fr_t *coset_factor_out, uint64_t cell_index, const KZGSettings *s
   579→) {
   580→    /*
   581→     * Get the cell index in reverse-bit order.
   582→     * This index points to this cell's coset factor h_k in the roots_of_unity array.
   583→     */
   584→    uint64_t cell_idx_rbl = CELL_INDICES_RBL[cell_index];
   585→
   586→    /*
   587→     * Get the index to h_k^n in the roots_of_unity array.
   588→     *
   589→     * Multiplying the index of h_k by n, effectively raises h_k to the n-th power,
   590→     * because advancing in the roots_of_unity array corresponds to increasing exponents.
   591→     */
   592→    uint64_t h_k_pow_idx = cell_idx_rbl * FIELD_ELEMENTS_PER_CELL;
   593→
   594→    /* Get h_k^n using the index */
   595→    assert(h_k_pow_idx < FIELD_ELEMENTS_PER_EXT_BLOB + 1);
   596→    *coset_factor_out = s->roots_of_unity[h_k_pow_idx];
   597→}
   598→
   599→/**
   600→ * Aggregate columns, compute the sum of interpolation polynomials, and commit to the result.
   601→ *
   602→ * This function computes `RLI = [sum_k r^k interpolation_poly_k(s)]` from the spec.
   603→ *
   604→ * @param[out]  commitment_out  Commitment to the aggregated interpolation poly
   605→ * @param[in]   r_powers        Precomputed powers of the random challenge, length `num_cells`
   606→ * @param[in]   cell_indices    Indices of the cells, length `num_cells`
   607→ * @param[in]   cells           Array of cells, length `num_cells`
   608→ * @param[in]   num_cells       Number of cells
   609→ * @param[in]   s               The trusted setup
   610→ */
   611→static C_KZG_RET compute_commitment_to_aggregated_interpolation_poly(
   612→    g1_t *commitment_out,
   613→    const fr_t *r_powers,
   614→    const uint64_t *cell_indices,
   615→    const Cell *cells,
   616→    uint64_t num_cells,
   617→    const KZGSettings *s
   618→) {
   619→    C_KZG_RET ret;
   620→    bool *is_cell_used = NULL;
   621→    fr_t *aggregated_column_cells = NULL;
   622→    fr_t *column_interpolation_poly = NULL;
   623→    fr_t *aggregated_interpolation_poly = NULL;
   624→
   625→    ////////////////////////////////////////////////////////////////////////////////////////////////
   626→    // Array allocations
   627→    ////////////////////////////////////////////////////////////////////////////////////////////////
   628→
   629→    ret = new_bool_array(&is_cell_used, CELLS_PER_EXT_BLOB);
   630→    if (ret != C_KZG_OK) goto out;
   631→    ret = new_fr_array(&aggregated_column_cells, FIELD_ELEMENTS_PER_EXT_BLOB);
   632→    if (ret != C_KZG_OK) goto out;
   633→    ret = new_fr_array(&column_interpolation_poly, FIELD_ELEMENTS_PER_CELL);
   634→    if (ret != C_KZG_OK) goto out;
   635→    ret = new_fr_array(&aggregated_interpolation_poly, FIELD_ELEMENTS_PER_CELL);
   636→    if (ret != C_KZG_OK) goto out;
   637→
   638→    ////////////////////////////////////////////////////////////////////////////////////////////////
   639→    // Aggregate cells from the same column
   640→    ////////////////////////////////////////////////////////////////////////////////////////////////
   641→
   642→    /* Start with zeroed out columns */
   643→    for (size_t i = 0; i < CELLS_PER_EXT_BLOB; i++) {
   644→        for (size_t j = 0; j < FIELD_ELEMENTS_PER_CELL; j++) {
   645→            size_t index = i * FIELD_ELEMENTS_PER_CELL + j;
   646→            aggregated_column_cells[index] = FR_ZERO;
   647→        }
   648→    }
   649→
   650→    /*
   651→     * Vertically collapse cells of the 2D matrix into a single array: `aggregated_column_cells`.
   652→     *
   653→     * For each provided cell, go over its field elements, and scale them by the appropriate power
   654→     * of r. Then aggregate all field elements on the same vertical slice into a single array.
   655→     */
   656→    for (uint64_t cell_index = 0; cell_index < num_cells; cell_index++) {
   657→        /* Determine which column this cell belongs to */
   658→        uint64_t column_index = cell_indices[cell_index];
   659→
   660→        /* Iterate over every field element of this cell: scale it and aggregate it */
   661→        for (size_t fr_index = 0; fr_index < FIELD_ELEMENTS_PER_CELL; fr_index++) {
   662→            fr_t original_fr, scaled_fr;
   663→
   664→            /* Get the field element at this offset */
   665→            size_t offset = fr_index * BYTES_PER_FIELD_ELEMENT;
   666→            ret = bytes_to_bls_field(
   667→                &original_fr, (const Bytes32 *)&cells[cell_index].bytes[offset]
   668→            );
   669→            if (ret != C_KZG_OK) goto out;
   670→
   671→            /* Scale the field element by the appropriate power of r */
   672→            blst_fr_mul(&scaled_fr, &original_fr, &r_powers[cell_index]);
   673→
   674→            /* Figure out the right index for this field element within the extended array */
   675→            size_t array_index = column_index * FIELD_ELEMENTS_PER_CELL + fr_index;
   676→            /* Aggregate the scaled field element into the array */
   677→            blst_fr_add(
   678→                &aggregated_column_cells[array_index],
   679→                &aggregated_column_cells[array_index],
   680→                &scaled_fr
   681→            );
   682→        }
   683→    }
   684→
   685→    ////////////////////////////////////////////////////////////////////////////////////////////////
   686→    // Determine which cells are used
   687→    ////////////////////////////////////////////////////////////////////////////////////////////////
   688→
   689→    /* Start with false values */
   690→    for (size_t i = 0; i < CELLS_PER_EXT_BLOB; i++) {
   691→        is_cell_used[i] = false;
   692→    }
   693→
   694→    /* Mark each cell index as used */
   695→    for (uint64_t i = 0; i < num_cells; i++) {
   696→        is_cell_used[cell_indices[i]] = true;
   697→    }
   698→
   699→    ////////////////////////////////////////////////////////////////////////////////////////////////
   700→    // Compute interpolation polynomials using the aggregated cells
   701→    ////////////////////////////////////////////////////////////////////////////////////////////////
   702→
   703→    /* Start with a zeroed out poly */
   704→    for (size_t i = 0; i < FIELD_ELEMENTS_PER_CELL; i++) {
   705→        aggregated_interpolation_poly[i] = FR_ZERO;
   706→    }
   707→
   708→    /* Interpolate each column */
   709→    for (size_t i = 0; i < CELLS_PER_EXT_BLOB; i++) {
   710→        /* We can skip columns without any cells */
   711→        if (!is_cell_used[i]) continue;
   712→
   713→        /* Offset to the first cell for this column */
   714→        size_t index = i * FIELD_ELEMENTS_PER_CELL;
   715→
   716→        /*
   717→         * Reach into the big array and permute the right column.
   718→         * No need to copy the data, we are not gonna use them again.
   719→         */
   720→        ret = bit_reversal_permutation(
   721→            &aggregated_column_cells[index], sizeof(fr_t), FIELD_ELEMENTS_PER_CELL
   722→        );
   723→        if (ret != C_KZG_OK) goto out;
   724→
   725→        /*
   726→         * Get interpolation polynomial for this column. To do so we first do an IDFT over the roots
   727→         * of unity and then we scale the coefficients by the coset factor. We can't do an IDFT
   728→         * directly over the coset because it's not a subgroup.
   729→         */
   730→        ret = fr_ifft(
   731→            column_interpolation_poly, &aggregated_column_cells[index], FIELD_ELEMENTS_PER_CELL, s
   732→        );
   733→        if (ret != C_KZG_OK) goto out;
   734→
   735→        /* Shift the poly by h_k^{-1} where h_k is the coset factor for this cell */
   736→        fr_t inv_coset_factor;
   737→        get_inv_coset_shift_for_cell(&inv_coset_factor, i, s);
   738→        shift_poly(column_interpolation_poly, FIELD_ELEMENTS_PER_CELL, &inv_coset_factor);
   739→
   740→        /* Update the aggregated poly */
   741→        for (size_t k = 0; k < FIELD_ELEMENTS_PER_CELL; k++) {
   742→            blst_fr_add(
   743→                &aggregated_interpolation_poly[k],
   744→                &aggregated_interpolation_poly[k],
   745→                &column_interpolation_poly[k]
   746→            );
   747→        }
   748→    }
   749→
   750→    ////////////////////////////////////////////////////////////////////////////////////////////////
   751→    // Commit to the aggregated interpolation polynomial
   752→    ////////////////////////////////////////////////////////////////////////////////////////////////
   753→
   754→    ret = g1_lincomb_fast(
   755→        commitment_out,
   756→        s->g1_values_monomial,
   757→        aggregated_interpolation_poly,
   758→        FIELD_ELEMENTS_PER_CELL
   759→    );
   760→    if (ret != C_KZG_OK) goto out;
   761→
   762→out:
   763→    c_kzg_free(is_cell_used);
   764→    c_kzg_free(aggregated_column_cells);
   765→    c_kzg_free(column_interpolation_poly);
   766→    c_kzg_free(aggregated_interpolation_poly);
   767→    return ret;
   768→}
   769→
   770→/**
   771→ * Compute weighted sum of proofs.
   772→ *
   773→ * @param[out]  weighted_proof_lincomb  The resulting G1 sum of the proofs scaled by coset factors
   774→ * @param[in]   proofs_g1               Array of proofs, length `num_cells`
   775→ * @param[in]   r_powers                Array of powers of r used for weighting, length `num_cells`
   776→ * @param[in]   cell_indices            Array of cell indices, length `num_cells`
   777→ * @param[in]   num_cells               The number of cells
   778→ * @param[in]   s                       The trusted setup
   779→ */
   780→static C_KZG_RET computed_weighted_sum_of_proofs(
   781→    g1_t *weighted_proof_sum_out,
   782→    const g1_t *proofs_g1,
   783→    const fr_t *r_powers,
   784→    const uint64_t *cell_indices,
   785→    uint64_t num_cells,
   786→    const KZGSettings *s
   787→) {
   788→    C_KZG_RET ret;
   789→    fr_t *weighted_powers_of_r = NULL;
   790→
   791→    ret = new_fr_array(&weighted_powers_of_r, num_cells);
   792→    if (ret != C_KZG_OK) goto out;
   793→
   794→    for (uint64_t i = 0; i < num_cells; i++) {
   795→        /* Get scaling factor h_k^n where h_k is the coset factor for this cell */
   796→        fr_t h_k_pow;
   797→        get_coset_shift_pow_for_cell(&h_k_pow, cell_indices[i], s);
   798→
   799→        /* Scale the power of r by h_k^n */
   800→        blst_fr_mul(&weighted_powers_of_r[i], &r_powers[i], &h_k_pow);
   801→    }
   802→
   803→    ret = g1_lincomb_fast(weighted_proof_sum_out, proofs_g1, weighted_powers_of_r, num_cells);
   804→
   805→out:
   806→    c_kzg_free(weighted_powers_of_r);
   807→    return ret;
   808→}
   809→
   810→/**
   811→ * Given some cells, verify that their proofs are valid.
   812→ *
   813→ * @param[out]  ok                  True if the proofs are valid
   814→ * @param[in]   commitments_bytes   The commitments for the cells, length `num_cells`
   815→ * @param[in]   cell_indices        The indices for the cells, length `num_cells`
   816→ * @param[in]   cells               The cells to check, length `num_cells`
   817→ * @param[in]   proofs_bytes        The proofs for the cells, length `num_cells`
   818→ * @param[in]   num_cells           The number of cells provided
   819→ * @param[in]   s                   The trusted setup
   820→ */
   821→C_KZG_RET verify_cell_kzg_proof_batch(
   822→    bool *ok,
   823→    const Bytes48 *commitments_bytes,
   824→    const uint64_t *cell_indices,
   825→    const Cell *cells,
   826→    const Bytes48 *proofs_bytes,
   827→    uint64_t num_cells,
   828→    const KZGSettings *s
   829→) {
   830→    C_KZG_RET ret;
   831→    g1_t interpolation_poly_commit;
   832→    g1_t final_g1_sum;
   833→    g1_t proof_lincomb;
   834→    g1_t weighted_sum_of_proofs;
   835→    g2_t power_of_s = s->g2_values_monomial[FIELD_ELEMENTS_PER_CELL];
   836→    size_t num_commitments;
   837→
   838→    /* Arrays */
   839→    Bytes48 *unique_commitments = NULL;
   840→    uint64_t *commitment_indices = NULL;
   841→    fr_t *r_powers = NULL;
   842→    g1_t *proofs_g1 = NULL;
   843→
   844→    *ok = false;
   845→
   846→    /* Exit early if we are given zero cells */
   847→    if (num_cells == 0) {
   848→        *ok = true;
   849→        return C_KZG_OK;
   850→    }
   851→
   852→    ////////////////////////////////////////////////////////////////////////////////////////////////
   853→    // Sanity checks
   854→    ////////////////////////////////////////////////////////////////////////////////////////////////
   855→
   856→    for (size_t i = 0; i < num_cells; i++) {
   857→        /* Make sure column index is valid */
   858→        if (cell_indices[i] >= CELLS_PER_EXT_BLOB) return C_KZG_BADARGS;
   859→    }
   860→
   861→    ////////////////////////////////////////////////////////////////////////////////////////////////
   862→    // Deduplicate commitments
   863→    ////////////////////////////////////////////////////////////////////////////////////////////////
   864→
   865→    ret = c_kzg_calloc((void **)&unique_commitments, num_cells, sizeof(Bytes48));
   866→    if (ret != C_KZG_OK) goto out;
   867→    ret = c_kzg_calloc((void **)&commitment_indices, num_cells, sizeof(uint64_t));
   868→    if (ret != C_KZG_OK) goto out;
   869→
   870→    /*
   871→     * Convert the array of cell commitments to an array of unique commitments and an array of
   872→     * indices to those unique commitments. We do this before the array allocations section below
   873→     * because we need to know how many commitment weights there will be.
   874→     */
   875→    num_commitments = num_cells;
   876→    memcpy(unique_commitments, commitments_bytes, num_cells * sizeof(Bytes48));
   877→    deduplicate_commitments(unique_commitments, commitment_indices, &num_commitments);
   878→
   879→    ////////////////////////////////////////////////////////////////////////////////////////////////
   880→    // Array allocations
   881→    ////////////////////////////////////////////////////////////////////////////////////////////////
   882→
   883→    ret = new_fr_array(&r_powers, num_cells);
   884→    if (ret != C_KZG_OK) goto out;
   885→    ret = new_g1_array(&proofs_g1, num_cells);
   886→    if (ret != C_KZG_OK) goto out;
